<?php
require_once '../config/session.php'; require_once '../config/config.php'; require_once '../config/functions.php';
if (empty($_SESSION['user_id']) || ($_SESSION['user_role'] ?? '') !== 'student') { header('Location: ../auth/login.php'); exit; }
$subscribed = has_active_subscription($conn, $_SESSION['user_id']);
$materials = $conn->query("SELECT m.*, s.name AS subject_name FROM study_materials m LEFT JOIN subjects s ON s.id=m.subject_id WHERE m.status='Active' ORDER BY m.uploaded_at DESC")->fetchAll(PDO::FETCH_ASSOC);
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Study Materials | ExamSphere</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.7/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.7.2/css/all.min.css"><link rel="stylesheet" href="assets/css/dashboard.css"><link rel="stylesheet" href="../assets/css/main.css"></head><body><?php include 'includes/navbar.php'; ?>
<main class="container py-5"><h1>Study materials</h1><p class="text-muted mb-4">Download public resources or activate a membership to unlock premium materials.</p><div class="row g-4"><?php foreach ($materials as $material): $locked = $material['access_type'] === 'Subscription Only' && !$subscribed; ?><div class="col-md-6 col-lg-4"><article class="card h-100 border-0 shadow-sm p-4"><div class="d-flex justify-content-between"><i class="fa-solid fa-file-pdf fa-2x text-danger"></i><span class="badge <?= $locked ? 'text-bg-secondary' : 'text-bg-success' ?>"><?= e($material['access_type']) ?></span></div><h5 class="mt-3"><?= e($material['title']) ?></h5><p class="small text-muted"><?= e($material['subject_name'] ?: 'General') ?> · <?= e($material['description']) ?></p><?php if ($locked): ?><a class="btn btn-outline-secondary mt-auto" href="subscriptions.php">Unlock with a plan</a><?php else: ?><a class="btn btn-primary mt-auto" href="download_material.php?id=<?= (int)$material['id'] ?>">Download</a><?php endif; ?></article></div><?php endforeach; ?></div><?php if (!$materials): ?><div class="alert alert-light border">No study materials are available yet.</div><?php endif; ?></main></body></html>
